import java.util.*;public class Main {static String[] mostPopular(String[] orders){if(orders==null||orders.length==0)throw new IllegalArgumentException();Map<String,Integer> counts=new HashMap<>();for(String s:orders){if(s==null)throw new IllegalArgumentException();counts.put(s,counts.getOrDefault(s,0)+1);}String best=orders[0];int max=counts.get(best);for(String s:orders)if(counts.get(s)>max){best=s;max=counts.get(s);}return new String[]{best,String.valueOf(max)};}public static void main(String[]args){String[] r=mostPopular(new String[]{"tea","coffee","coffee","tea"});System.out.println("("+r[0]+", "+r[1]+")");System.out.println("Hash map approach: O(n) time and O(u) extra space.");}}